34.frame_eqs_str:
warp = 0;
//zoom = 1;

tic = min(time-tin,.1);
tin = time;

vol = (bass_att + treb_att + mid_att)*.333333;

ra = 1/tic*.25;

treb_avg = tic*(treb_avg*(1/tic - ra) + ra*treb);
mid_avg = tic*(mid_avg*(1/tic - ra) + ra*mid);
bass_avg = tic*(bass_avg*(1/tic - ra) + ra*bass);
vav = tic*(vav*(1/tic - ra) + ra*(bass+treb+mid)*.33333);

tt = tt + tic*treb;
mt = mt + tic*mid;
bt = bt + tic*bass;
vt = vt + tic*vav;

q1 = tt*2.1;// wave morph speeds
q2 = mt*3;
q3 = bt*3;

q4 = vt; // wave colour cycle

rb = if(rb,rb,.2 + rand(1001)*.001*.6);
rc = if(rc,rc,.2 + rand(1001)*.001*.6);
rd = if(rd,rd,.2 + rand(1001)*.001*.6);
re = if(re,re,.2 + rand(1001)*.001*.6);


ti = vt*2;
cx = .3 + .1*sin(ti*re) + .1*cos(ti*rd);
cy = .5 + .2*sin(ti*rb) + .1*cos(ti*re);


q7 = 6;
q8 = 2.8;

34.pixel_eqs_str:
xnum = q7;
ynum = q8;
pi = 3.141592654;

xseg = int(x*xnum);
yseg = int(y*ynum);

xsw = equal((xseg+equal(yseg%2,0))%2,0);
ysw = equal((yseg+1)%2,0);


ox = x - xseg*(1/xnum);
ox = if(xsw,1/xnum - ox,ox);

oy = y - yseg*(1/ynum);
oy = if(ysw,1/ynum - oy,oy);

dx = above(xseg+yseg,0)*(x-ox);
dy = above(xseg+yseg,0)*(y-oy);

rot = rot*(1-above(xseg+yseg,0));

//dx = equal(seg,1)*(x - .5)*2;

34.warp:
shader_body
{
    // sample previous frame
    ret = tex2D( sampler_main, uv ).xyz*.85;

    // darken over time
    ret -= 0.002;
}

34.comp:
shader_body
{
float2 uv1 = (uv-0.5)*aspect.xy;

//float ang1 = atan2(uv1.y, uv1.x);
//float rad1 = log(length(uv1)-0.1);

float rad2 = length(uv1) + .1;
float rad1 = .1/rad2 ;

float2 uv2 = float2 (ang/3.14, rad1*2.2);
uv2.y = uv2.y  +0.25*time;
//uv2.x = uv2.x  +.0*time;
uv2.x = uv2.x + time/32;

float2 uv3 = float2 (ang/3.14, rad1*3.5);
uv3.y = uv3.y  +0.08*time ;
//uv3.y = uv3.y  + time/32;
uv3.x = uv3.x + 0.08*time;

float3 crisp = 1*GetPixel(uv2) + GetPixel(uv3);
crisp += 2*GetBlur2(frac(uv2)) + 2*GetBlur2(frac(uv3));

float3 lay1 = float3 (0,0,1)*uv.y*pow(1-rad,8);

crisp = 3.5*crisp * pow(rad,1);

float mask = saturate(1-200*rad);

ret = crisp + lay1*mask + mask * GetPixel(uv);

}

