228.warp:
shader_body
{
    float t = saturate((bass/bass_att-0.9)*13);
    uv = lerp(uv_orig, uv, t*0.9);

    float2 v1 = normalize(uv_orig-0.5);
    float2 v2 = v1.yx * float2(1,-1);

    float z = length(texsize.zw)*900;

    uv.xy += v1*texsize.zw * cos(rad*10 - time*8)*5;
    uv.xy += v2*texsize.zw * cos(ang*5 - time*8)*15;

    // sample previous frame
    ret = tex2D( sampler_main, uv ).xyz;



    // darken (decay) over time
    ret = (ret - 0.11)*0.9;
}

228.comp:
shader_body
{
    float rad_lq = rad * length(texsize.xy)*0.5;
    float ang_lq = ang;

    float2 uv2 = (uv - 0.5);
    float rad2 = rad_lq*0.8;
    float ang2 = ang_lq * M_INV_PI_2;

        ang2 += time*0.015 - rad_lq*0.0002;
        float fins = 7;
          ang2 = frac(ang2*fins)/fins;
          ang2 = abs(ang2 - 0.5/fins);

    ang2 *= M_PI_2;
    uv2 = 0.5 + rad2*float2(cos(ang2),sin(ang2))*texsize.zw;

    ret = tex2D(sampler_main, uv2).xyz;
    ret *= 1.333; // a little bit of overbright
}

