272.frame_eqs_str:
//krash's beat detection code
volume = 0.3*(bass+mid+att);
beatrate = equal(beatrate,0) + (1-equal(beatrate,0))*(below(volume,0.01) + (1-below(volume,0.01))*beatrate);
lastbeat = lastbeat + equal(lastbeat,0)*time;
meanbass_att = 0.1*(meanbass_att*9 + bass_att);
peakbass_att = max(bass_att,peakbass_att);
beatrate = max(if(beat,if(below(time-lastbeat,2*beatrate),0.1*(beatrate*9 + time - lastbeat),beatrate),beatrate),0.1);
peakbass_att = beat*bass_att + (1-beat)*peakbass_att*(above(time - lastbeat, 2*beatrate)*0.95 + (1-above(time - lastbeat, 2*beatrate))*0.995);
lastbeat = beat*time + (1-beat)*lastbeat;
peakbass_att = max(peakbass_att,1.1*meanbass_att);
beat = above(volume,0.8)*below(peakbass_att - bass_att, 0.05*peakbass_att)*above(time - lastbeat, 0.1 + 0.5*(beatrate - 0.1));
beatcounter = beatcounter + beat;
mode = if(beat*equal(beatcounter%2,0),1-mode,mode);
flip = 2*mode-1;
monitor=flip;
q8=flip;
q7=0;

decay=0.88;
zoom=1.002;

vol=(bass_att+mid_att+treb_att)*0.25;
vol=vol*vol;
mtime=mtime+vol*0.1*flip;

q1=mtime*0.4;

warp=0.3

272.warp:
shader_body
{
    float t = saturate((bass/bass_att-0.9)*13);
    uv = lerp(uv_orig, uv, t*0.3);

    float2 v1 = normalize(uv_orig-0.5);
    float2 v2 = v1.yx * float2(1,-1);

    float z = length(texsize.zw)*450;

    uv.xy += v1*texsize.zw * cos(rad*170 - time*7)*2;
    uv.xy += v2*texsize.zw * cos(ang*30 - time*7)*5;

    // sample previous frame
    ret = tex2D( sampler_main, uv ).xyz;



    // darken (decay) over time
    ret = (ret - 0.004)*0.83;
}

272.comp:
shader_body
{



float2 uva = uv;
float2 uvb = float2(1-uv.x,uv.y);

ret = tex2D(sampler_main, uva).x + tex2D(sampler_main, uvb).x;

float3 blurs = GetBlur1(uva).x + GetBlur3(uva).x;
blurs += GetBlur1(uvb).x + GetBlur3(uvb).x;


float2 uv3 = (uv-.5)*(1-GetBlur1(uv).zzz)+.5;
ret += saturate(pow(tex2D(sampler_main, uv3).zzz,.5)*(1-ret.x*2)),
ret += saturate(pow(GetBlur1(uv3).zzz,.5)*(1-ret.x*2)),
ret = lerp (blurs,ret,pow(ret,1));
ret = pow(ret,.8+4*roam_cos);
ret += pow(tex2D(sampler_main, float2(uv.x,1-uv.y)).yyy+tex2D(sampler_main, 1-uv).yyy,float3(.6,.95,5));

ret = 1-exp(-2*ret);
}

