282.warp:
shader_body
{
    float t = saturate((bass/bass_att-0.9)*13);
    uv = lerp(uv_orig, uv, t*0.3);

    float2 v1 = normalize(uv_orig-0.5);
    float2 v2 = v1.yx * float2(1,-1);

    float z = length(texsize.zw)*450;

    uv.xy += v1*texsize.zw * cos(rad*170 - time*7)*2;
    uv.xy += v2*texsize.zw * cos(ang*30 - time*7)*5;

    // sample previous frame
    ret = tex2D( sampler_main, uv ).xyz;



    // darken (decay) over time
    ret = (ret - 0.004)*0.83;
}

282.comp:
shader_body
{
    uv = 0.05 + 0.9*uv;

    // equivalent of a laplacian: [center*4 - each of the 4 neighbors*1]
    ret = 0;
    ret += tex2D(sampler_main, uv ).xyz*4;
    ret -= GetBlur1(uv)*4;
ret *= -1;

    // little bit of noise:
    ret *= 1 + 0.12*(tex2D(sampler_noise_lq, rand_frame.xy 
           + uv*texsize.xy*texsize_noise_lq.zw).xxx*2-1);

    // palettize:
    ret = pow(ret, float3(0.5, 0.5, 0.7));

    ret = (ret-0.1)*1.1;

    //ret.xyz *= 2; // a little bit of overbright
}

