//g *= aspect.xy * cos(16*(.5-rad)*ang); //ok
uv += arg*texsize.zw* (1+ 4 * q28);

float3 crisp = tex2D(sampler_main,uv);

ret = q32*crisp + noiseVal*.8-.03;
}

