custom10.frame_eqs_str:
//krash's beat detection code
volume = 0.3*(bass+mid+att);
beatrate = equal(beatrate,0) + (1-equal(beatrate,0))*(below(volume,0.01) + (1-below(volume,0.01))*beatrate);
lastbeat = lastbeat + equal(lastbeat,0)*time;
meanbass_att = 0.1*(meanbass_att*9 + bass_att);
peakbass_att = max(bass_att,peakbass_att);
beatrate = max(if(beat,if(below(time-lastbeat,2*beatrate),0.1*(beatrate*9 + time - lastbeat),beatrate),beatrate),0.1);
peakbass_att = beat*bass_att + (1-beat)*peakbass_att*(above(time - lastbeat, 2*beatrate)*0.95 + (1-above(time - lastbeat, 2*beatrate))*0.995);
lastbeat = beat*time + (1-beat)*lastbeat;
peakbass_att = max(peakbass_att,1.1*meanbass_att);
beat = above(volume,0.8)*below(peakbass_att - bass_att, 0.05*peakbass_att)*above(time - lastbeat, 0.1 + 0.5*(beatrate - 0.1));
beatcounter = beatcounter + beat;
mode = if(beat*equal(beatcounter%2,0),1-mode,mode);
flip = 2*mode-1;
monitor=flip;
q8=flip;


decay=1;
zoom=1.002;

vol=(bass_att+mid_att+treb_att)*0.25;
vol=vol*vol;
mtime=mtime+vol*0.1*flip*(55/fps);

q1=mtime*0.4;

warp=0.0

custom10.warp:
shader_body
{
    ret.x = tex2D( sampler_main, (uv-0.5)*1.00+0.5 ).x;
    ret.y = tex2D( sampler_main, (uv-0.5)*0.98+0.5 ).y;
    ret.z = tex2D( sampler_main, (uv-0.5)*0.95+0.5 ).z;

    // .x = fastest layer, .z = slowest
    float r = 2; 
    ret += float3(-ret.x,ret.x,0)*0.06*r;
    ret += float3(0,-ret.y,ret.y)*0.05*r;     
    ret += float3(0,0,-ret.z)*0.04*r;     

    // ERROR DIFFUSION DITHER - looks great
    float2 dither_uv = uv_orig*texsize.xy*texsize_noise_lq.zw + rand_frame.xy;
    ret += (tex2D(sampler_noise_lq, dither_uv).xyz-0.5)/256.0*float3(3,5,8);

    // darken over time
    ret -= 0.0005;
    //ret *= 0.99;
    //ret *= 0.97 + 0.03*saturate( length(uv - uv_orig)*200 );  // center only
}

custom10.comp:
shader_body
{
    ret = tex2D(sampler_main, uv).xyz;
    ret = ret*1.5 - 0.1;

    float4 g;
    float3 d = float3(texsize.zw * 4, 0);
    g.x = lum(GetBlur1(uv + d.xz));
    g.y = lum(GetBlur1(uv - d.xz));
    g.z = lum(GetBlur1(uv + d.zy));
    g.w = lum(GetBlur1(uv - d.zy));

    ret *= 0.7;
    ret.x += saturate(g.x-g.y)*5;
    ret.z += saturate(g.y-g.x)*5;
    //ret.xy += (g.xz-g.yw)*3;

ret.x = GetBlur1(uv).x*2;
ret.z = GetBlur2(uv).z*3;

}

