    float3 dy = ( GetBlur1(uv+float2(0,1)*d)-GetBlur1(uv-float2(0,1)*d) );

float2 uv_x = uv - float2(dx.z,dy.z)*0.1 + float2(dx.y,dy.y)*0.06;
ret = GetBlur2(uv_x).x*saturate(1-GetPixel(uv).z)*pow(hue_shader.yxz,8)*3;
float4 noise9 = tex3D(sampler_noisevol_hq, 
