{
    sam = tex2D(sampler_main,uv*.5);
    ret1 = tex2D(sampler_main, float2(uv.x, uv.y));
    sam *= GetBlur1(uv)-GetBlur3(uv);       

    reta = tex2D(sampler_main, sam+uv ).rgb;
    ret1 = reta.r * (.5*bass_att*uv_orig.y+reta) + (reta.r)*ret1;
    ret1 *= (ret1+1)/2; //gamma

uv = (uv-.5)*.3+.5;
    sam = tex2D(sampler_main,uv*.5);
