    reta = tex2D(sampler_main, sam+uv ).rgb;
    ret2 = reta.r * (.5*bass_att*uv_orig.y+reta) + (reta.r)*ret2;
    ret2 *= (ret1+1); //gamma



ret = max(ret1, ret2);
