Halfbreak - 2D Purple Fires.comp:
shader_body
{
float2 d = texsize.zw*8;
float3 dx = ( GetBlur1(uv+float2(1,0)*d)-GetBlur1(uv-float2(1,0)*d) );
float3 dy = ( GetBlur1(uv+float2(0,1)*d)-GetBlur1(uv-float2(0,1)*d) );

float2 uv_fire = uv + float2(dx.z,dy.z)*0.02 - float2(dx.y,dy.y)*texsize.zw*16;
ret = GetBlur3(uv_fire).y*float3(1.7,0,0);
ret = lerp(ret, float3(-0.4,-0.5,0), GetBlur1(uv_fire).y*1.2);
ret = lerp(ret, float3(2,2,0),GetPixel(uv_fire).y*0.9);


uv += float2(dx.z, dy.z)*texsize.zw*2;

ret = lerp(ret, 0, GetBlur1(uv).z*2);
ret = lerp(saturate(ret), float3(0.7,0.6,1), GetPixel(uv).z);

ret = lerp(ret, float3(1,0.9,0.9), saturate(GetPixel(uv).x*2-1)*1.2);
}

