mid_avg = tic*(mid_avg*(1/tic - ra) + ra*mid);
bass_avg = tic*(bass_avg*(1/tic - ra) + ra*bass);
vav = tic*(vav*(1/tic - ra) + ra*(bass+treb+mid)*.33333);

tt = tt + tic*treb_avg;
mt = mt + tic*mid_avg;
bt = bt + tic*bass_avg;

sp = abs(vav - slide)*.1;
slide = if(above(slide,vav),slide-tic*sp,slide+tic*sp) + (1-toc)*vav;
toc = 1;

vt = vt + tic*slide;

q1 = bt;
q2 = mt;
q3 = tt;
q4 = slide*1;
q5 = vt*.05 + 150;

q6 = .01;//tic;

Isosceles mashup13.warp:
shader_body
{
    // sample previous frame
    ret = tex2D( sampler_main, uv ).xyz;
    float3 ret2 = tex2D( sampler_fc_main, uv ).xyz;

    ret.x = tex2D( sampler_main, (uv-0.5)*1.00+0.5 ).x;
    ret.y = tex2D( sampler_main, (uv-0.5)*0.98+0.5 ).y;
    ret.z = tex2D( sampler_main, (uv-0.5)*0.96+0.5 ).z;   

    // darken (decay) over time
    ret = ret- (ret*.5);
    ret = ret*(abs(GetBlur2(uv)-.5))*5;
    ret = ret - .01;
}

