    float3 dy = ( GetBlur1(uv_orig+float2(0,1)*d)-GetBlur1(uv_orig-float2(0,1)*d) );

float2 uv_red = 0.5 + (uv-0.5)*0.996 - float2(0,1)*texsize.zw - float2(dx.x,dy.y)*texsize.zw*4;

