float2 numerator, denominator, fraction;
shader_body
{
numerator = float2(q13,q14);
denominator = uv+float2(-q5,q6)-float2(0,1);
fraction = float2( numerator.x*denominator.x + numerator.y*denominator.y,   // the fractions real part
                   numerator.y*denominator.x - numerator.x*denominator.y)/  // the fractions imaginary part
                   (denominator.x*denominator.x + denominator.y*denominator.y);
fraction *=.002;
float2 inv = lerp(0.5+(uv-0.5)*2,fraction+0.5,0.5); //uv vector for the spinal fractal
float2 dither_uv = uv_orig*texsize.xy*texsize_noise_lq.zw * 2 + rand_frame.xy;
float3 noise = tex2D(sampler_noise_lq, dither_uv).xyz-0.5;
float2 d = texsize.zw*4;
float3 dx = ( GetBlur1(uv + float2(1,0)*d) - GetBlur1(uv-float2(1,0)*d) );
float3 dy = ( GetBlur1(uv + float2(0,1)*d) - GetBlur1(uv-float2(0,1)*d) );
float2 uv1 = uv + (float2(dx.x, dy.x)*0.4+noise*2)*texsize.zw;
float2 uv2 = float2(dx.y, dy.y)*texsize.zw*6;
float2 uv3 = uv + (float2(dx.z, dy.z)*0.5+noise*2)*texsize.zw ;
ret.x = GetPixel(uv1).x;
ret.z = GetPixel(uv3).z;
ret.y = GetPixel(inv+uv2).y;
ret += noise*0.04-0.0018; // when using an error diffusion dither you can decay to black on a rate below 1 bit

}

