shader_body
{
//ret=tex2D(sampler_main,uv);
// ***** Flexis rotating caleidoscope code *****
float2 cntr = float2(q13,q14); float sin = q11; float cos = q12; float scale = q15;
float2 uv_r = (uv-cntr)*aspect.xy;
       uv_r = scale*float2( cos*uv_r.x - sin*uv_r.y, sin*uv_r.x + cos*uv_r.y); // rotation
       uv_r = cntr + uv_r*aspect.zw;
       uv_r = 1.0 - abs( frac( uv_r * 0.5 ) * 2.0 - 1.0 ); // mirror
sin = q17; cos = q18; scale = q16;
float2 uv_rr = (uv_r-cntr);
       uv_rr = scale*float2( cos*uv_rr.x - sin*uv_rr.y, sin*uv_rr.x + cos*uv_rr.y); // counter-rotation
       uv_rr = cntr + (uv_rr);
float t = q22;
float2 c = ((uv_rr-0.5));
float1 ang_hq = atan2(c.x,c.y);
float2 spiral = float2(ang_hq*q21*1.5,0.666*log(length(c))-ang_hq*q21+t);
spiral = 0.5 + (0.5 - abs( frac( spiral * 0.5 ) * 2.0 - 1.0 ))*float2(0.96,1.02); // mirror
ret = GetPixel(saturate(spiral));


float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv_rr.xyy*q28
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q31
                     );
if(ret.x> q26*q13         && ret.x<= q23*q11        )ret.z -= (noise9).x*.5; 
if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5; 
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5; 
ret=pow(GetBlur1(uv).xyz/treb_att,1-lum(saturate(ret.xyz)));
ret=pow(GetBlur2(uv).xyz/bass_att,1-lum(saturate(ret.xyz)));
ret=1-ret;
}

