shader_body
{
float2 pixelsize = texsize.zw;

float zm = q5;
float2 cen = float2(q11,q12);
float2 uvo = (uv_orig-cen)*zm + cen;

float2 uvm = uv_orig;

float2 noise_uv = uv_orig*texsize.xy*texsize_noise_lq.zw + rand_frame.xy;
float4 noiseVal = tex2D(sampler_noise_lq, noise_uv);

ret.xy = tex2D( sampler_pw_main,uvo).xy;
ret.xy = (ret.xy-cen)/zm+cen;

float2 uv2 = uv_orig  + (noiseVal.xy-.5)*12*pixelsize;
float3 rsamp = tex2D(sampler_pw_main,frac(uv2)).xyz;

rsamp.xy = (rsamp.xy-cen)/zm+cen;

float4 len = (float4(ret.xy,rsamp.xy) - uvm.xyxy);
float l1 = length(len.xy);
if (l1 > length(len.zw)) ret.xy = rsamp.xy;

uv2 = uv_orig  + (noiseVal.zw-.5)*48*pixelsize;
rsamp = tex2D(sampler_pw_main,frac(uv2)).xyz;
rsamp-=roam_sin.wzy*roam_cos.zxy;
rsamp.xy = (rsamp.xy-cen)/zm+cen;
len.zw = rsamp.xy - uvm.xy;
if (l1 > length(len.zw)) ret.xy = rsamp.xy;

//uv2 = uv_orig  + (noiseVal.zw-.5)*6*pixelsize;
//rsamp = tex2D(sampler_pw_main,frac(uv2)).xyz;
//len = abs(float4(ret.xy,rsamp.xy) - uvm.xyxy);
//if (length(len.xy) > length(len.zw)) ret.xy = rsamp.xy;

//float2 uvo = (uv_orig-cen)*zm + cen;
