ret.z = 0;

}

Tripgnosis - Dark Matter Glowstix hog ro.comp:
float3 reta;
float3 retb;
float3 retc;

shader_body
{



uv = 0.5 + (uv-0.5)*0.98;
    float2 d = texsize.zw*4;
    float3 dx = ( GetBlur1(uv+float2(1,0)*d)-GetBlur1(uv-float2(1,0)*d) );
    float3 dy = ( GetBlur1(uv+float2(0,1)*d)-GetBlur1(uv-float2(0,1)*d) );

float4 noise = tex3D(sampler_noisevol_hq, ((uv.xyy+float3(lum(dx),lum(dy),0)*0.5)*texsize.xyy*texsize_noisevol_hq.zww).xyz*float3(1,1,0)*0.05
                                        + time*float3(0,0,1)*0.2 );
uv -= float2(lum(dx),lum(dy))*0.04;
ret = abs(GetPixel(uv)+GetBlur1(uv)-GetBlur2(uv)-GetBlur3(uv));
ret-=roam_sin.zyx*roam_cos.ywx;
ret *= lum(noise)*3; 
ret = pow(ret,0.5);



float2 uv2 = uv*0.25;
float3 col = 0;
float2 uv3 = uv2;
for(int i = 0; i<16; i++){
    uv3 += i*float2(0.25,0) - (0==(i)%4)*float2(0,0.25);
    col = lerp(col,i/16.0,saturate(-GetPixel(uv3).y+tex2d(sampler_pw_main,frac(uv3)).y));


}


reta = lerp(GetPixel(uv).z*float3(0.6,0.2,1),float3(1,1,1),col*saturate(1-GetBlur1(uv).x*2));
retb = lerp(GetPixel(uv).z*float3(0.6,0.2,1),float3(1,1,1),col*saturate(1-GetBlur1(uv).x*2));
    float gx = GetPixel(uv+float2(1,0)*texsize.zw) - GetPixel(uv-float2(1,0)*texsize.zw);
    float gy = GetPixel(uv+float2(0,1)*texsize.zw) - GetPixel(uv-float2(0,1)*texsize.zw);
    float3 g = normalize(float3(gx, gy, .04));

    reta = lerp(ret,float3(1.1,0.8,0.5),(dot(g.xyz,float3(frac(uv)-0.5,0.6))*0.5+0.5)*GetPixel(frac(uv)).x);
    retb = lerp(ret,float3(1.1,0.8,0.5),(dot(g.xyz,float3(frac(uv)-0.5,0.6))*0.5+0.5)*GetPixel(frac(uv)).x);

//retc = lerp(ret,retb,(sin(time)*100));
ret = lerp(ret,reta,q20);
retc = lerp(ret,retb,(sin(time)*100));
ret = lerp(ret,retc,q20);

ret = 1 - ret;
ret *= treb_att * .5;
}

