Tripgnosis - Dark Matter Glowstix nz.warp:
#define MyGet GetPixel //GetBlur1
shader_body
{
    // GROW EFFECT - bright pixels spread radially outward.
    // BE CAREFUL - this can really thrash the texture cache! (SLOW)
    float grad_rad = 4;  //TWEAK
    float str = 2.8;      //TWEAK
    float3 d = float3(texsize.zw, 0) * grad_rad;
    float4 lums = 0;
    lums.x = lum( MyGet(uv + texsize.zw*d.xz) );
    lums.y = lum( MyGet(uv - texsize.zw*d.xz) );
    lums.z = lum( MyGet(uv + texsize.zw*d.zy) );
    lums.w = lum( MyGet(uv - texsize.zw*d.zy) );
    float2 grad = float2(lums.x-lums.y, lums.z-lums.w)*str*1000/grad_rad;
    grad = (saturate(grad*0.5+0.5)*2-1)*1.4;
    // sample previous frame
    ret = tex2D( sampler_fc_main, uv + grad*texsize.zw ).xyz;

    // darken (decay) over time
    ret *= 0.983; //or try: ret -= 0.004;
float4 noise2 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*0.4 
                     );
ret -= (noise2)*.2; 
}

Tripgnosis - Dark Matter Glowstix nz.comp:
shader_body
{
    uv = 0.05 + 0.9*uv;

    // equivalent of a laplacian: [center*4 - each of the 4 neighbors*1]
    ret = 0;
    ret += tex2D(sampler_main, uv ).xyz*4;
    ret -= GetBlur1(uv)*4;
ret *= -1;

    // little bit of noise:
    //ret *= 1 + 0.12*(tex2D(sampler_noise_lq, rand_frame.xy 
    //       + uv*texsize.xy*texsize_noise_lq.zw).xxx*2-1);

    // palettize:
    ret = pow(ret, float3(0.5, 0.5, 0.7));

    ret = (ret-0.1)*1.1;

float4 noise2 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy*.6
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*0.4 
                     );
ret *= (noise2)*1.3; 
}

