mv_x=64;mv_y=48;
nut=0;
stp=0;stq=0;
rtp=0;rtq=0;
wvr=0;
decay=0;
dcsp=0

Tripgnosis - Firesticks --- Isosceles ed.warp:
shader_body
{
    uv -= 0.5;
    uv *= 1 + (q4*uv.y + q5*uv.x)*0.1;
    uv += 0.5;

    // sample previous frame
    ret = tex2D( sampler_main, uv ).xyz;


    ret = max(ret,  tex2D(sampler_main, uv + (ret.xy-0.5)*texsize.zw*13*float2(q5,-q4)).xyz );   

    // darken (decay) over time
    ret = (ret - 0.003)*0.98;
}

Tripgnosis - Firesticks --- Isosceles ed.comp:
shader_body
{
    ret = tex2D(sampler_main, uv).xyz;
      // GLOWING EDGES - looks awesome w/octopus
      float3 avg_col = GetBlur1(uv);
      ret = abs(avg_col - ret)*4;
    //ret *= 1.333; // a little bit of overbright
}

