Tripgnosis - Glowsticks (Blacklight Remi.comp:
float2 d, uv_y;
float3 dx, dy;
shader_body
{

    d = texsize.zw*18;
    dx = ( GetBlur1(uv+float2(1,0)*d)-GetBlur1(uv-float2(1,0)*d) );
    dy = ( GetBlur1(uv+float2(0,1)*d)-GetBlur1(uv-float2(0,1)*d) );

float base = GetPixel(uv);
float emboss = (-dx + dy + 1);

    d = texsize.zw*4;
    dx = ( GetBlur1(uv+float2(1,0)*d)-GetBlur1(uv-float2(1,0)*d) );
    dy = ( GetBlur1(uv+float2(0,1)*d)-GetBlur1(uv-float2(0,1)*d) );

float grad = length(float2(dx.x,dy.x))*0.6;

ret = lerp( float3(0.5,0.3,0)*base.x*emboss,
            float3(8,7,0)*grad,
            grad
          ); 
ret-=roam_sin.wzy*roam_cos;
ret = lerp(ret,float3(0.2,0,0.4),saturate(GetPixel(uv+float2(dx.x,dy.x)*0.2 + float2(dx.z,dy.z)*0.04).z-GetBlur1(uv).x*2));
ret = lerp(ret,float3(1,1,1),GetPixel(uv+float2(dx.y,dy.y)*0.01+float2(dx.x,dy.x)*0.2).y);
}

