shader_body
{

    // sample previous frame
    float3 a = tex2D(sampler_main, uv).xyz;
    float3 b = GetBlur1(uv)*5;

    float2 uv2 = uv + (a-b).xy*texsize.zw*3;
    ret = tex2D(sampler_main, uv2).xyz;

    // add noise
    float t = 0.013;
    ret += (tex2D(sampler_noise_lq, uv_orig.xy*texsize.xy*texsize_noise_lq.zw).xyz*2-1)*t;

    // darken
    ret -= 0.00014;
}

Tripgnosis - Neon Danse friends, never r.comp:
shader_body
{
float3 rnd = tex2D(sampler_noise_lq, rand_frame.xy + uv*texsize.xy*texsize_noise_lq.zw)*2-1;

ret = GetPixel(uv);

float2 d = texsize.zw * 8;
float3 dx = ( GetBlur1(uv + float2(1,0)*d) - GetBlur1(uv-float2(1,0)*d) );
float3 dy = ( GetBlur1(uv + float2(0,1)*d) - GetBlur1(uv-float2(0,1)*d) );

uv -= float2(lum(dx),lum(dy))*texsize.zw*32;


ret = pow(abs(GetBlur3(uv+rnd.xy*texsize.zw*5)*2-GetPixel(uv))*1.6,2)*0.9;

}

