Tripgnosis - Neon Danse.warp:
shader_body
{
    float t = saturate((bass/bass_att-0.9)*13);
    uv = lerp(uv_orig, uv, t*0.3);

    float2 v1 = normalize(uv_orig-0.5);
    float2 v2 = v1.yx * float2(1,-1);

    float z = length(texsize.zw)*450;

    uv.xy += v1*texsize.zw * cos(rad*170 - time*7)*2;
    uv.xy += v2*texsize.zw * cos(ang*30 - time*7)*5;

    // sample previous frame
    ret = tex2D( sampler_main, uv ).xyz;



    // darken (decay) over time
    ret = (ret - 0.004)*0.83;
}

Tripgnosis - Neon Danse.comp:
sampler sampler_ruin;
shader_body
{
  ret = tex2D(sampler_main,uv).xyz;
  float2 uv3 = float2(uv.x+((.2*mid)*sin(time)),uv.y+((.2*mid)*sin(time*.3456787)));
  float3 ret3 = tex2D(sampler_main,uv).xyz;
  float2 uv2 = float2(uv.y,abs(uv.x-1));
  float3 ret2 = tex2D(sampler_main,uv2).xyz;
  ret += ret*ret*10;
  ret2 += ret2*ret2*10;
  ret3 += ret3*ret3*5*treb;
  ret = lerp(ret2,ret,.5);
  ret = lerp(ret,ret3,ret*bass);
}

