Tripgnosis - Sparkler Rave nz+.warp:
shader_body
{
  // sample previous frame
  ret = tex2D( sampler_pw_main, uv ).xyz;

  float n;
  float2 d = texsize.zw*1;
  n  = saturate(tex2D(sampler_pw_main, uv+d*float2( 1, 1)).x*999);
  n += saturate(tex2D(sampler_pw_main, uv+d*float2( 1, 0)).x*999);
  n += saturate(tex2D(sampler_pw_main, uv+d*float2( 1,-1)).x*999);
  n += saturate(tex2D(sampler_pw_main, uv+d*float2( 0, 1)).x*999);
  n += saturate(tex2D(sampler_pw_main, uv+d*float2( 0,-1)).x*999);
  n += saturate(tex2D(sampler_pw_main, uv+d*float2(-1, 1)).x*999);
  n += saturate(tex2D(sampler_pw_main, uv+d*float2(-1, 0)).x*999);
  n += saturate(tex2D(sampler_pw_main, uv+d*float2(-1,-1)).x*999);

  if (n < 1.5)
    ret = 0;
  if (n > 3.5)
    ret = 0;
  if (ret.x < 0.1 && abs(n-3) < 0.5)
    ret = 1;

float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy*q27
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q29
                     );
if(ret.x> q21*roam_cos.y && ret.x<= q24*roam_sin.x)ret.x += (noise9).x*1.5; 
if(ret.y> q22*roam_sin.x && ret.y<= q25*roam_cos.x)ret.y -= (noise9).y*.5; 
if(ret.z> q23*roam_cos.x && ret.z<= q26*roam_sin.y)ret.z *= (noise9).z*1.5; 

}

