    float2 texc = 0.4 + float2(ret.x, time*0.003);
    ret = tex2D(sampler_seaweed, texc) * ret.z * 3;

float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy*q28
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q30 
                     );
if(ret.x> q26*roam_cos.y && ret.x<= q23*roam_sin.x)ret.x *= (noise9).x*1.5; 
if(ret.y> q25*roam_sin.x && ret.y<= q22*roam_cos.x)ret.y += (noise9).y*1.5; 
if(ret.z> q24*roam_cos.x && ret.z<= q21*roam_sin.y)ret.z -= (noise9).z*.5; 
}

