$$$ Royal - Mashup (70).warp:
shader_body
{

    float2 d = 0.02*aspect.zw;
    float3 dx = ( GetBlur2(uv+float2(1,0)*d-floor(uv+float2(1,0)*d))-GetBlur2(uv-float2(1,0)*d-floor(uv-float2(1,0)*d)) );
    float3 dy = ( GetBlur2(uv+float2(0,1)*d-floor(uv+float2(0,1)*d))-GetBlur2(uv-float2(0,1)*d-floor(uv-float2(0,1)*d)) );
    float3 b1 = GetBlur1(uv) - 0;
    d = 0.01;
    float d2 = -0.02;
    float1 thr = 0;
    float1 c = 0.005;


    float2 my_uv = uv - float2(dx.y,dy.y)*d - float2(dy.x,-dx.x)*d2;
    ret.y = tex2D( sampler_fc_main, my_uv-floor(my_uv)).y;
    ret.y += (ret.y - b1.y - thr)*.02 +c;


    my_uv = uv - float2(dx.x,dy.x)*d - float2(dy.z,-dx.z)*d2;
    ret.x = tex2D( sampler_fc_main, my_uv-floor(my_uv)).x;
    ret.x += (ret.x - b1.x - thr)*.02 +c;


    my_uv = uv - float2(dx.z,dy.z)*d - float2(dy.y,-dx.y)*d2;
    ret.z = tex2D( sampler_fc_main, my_uv-floor(my_uv)).z;
    ret.z += (ret.z - b1.z - thr)*.02 +c;


}

