  // diffused version:
  float ss = 0.3;
  float3 blur = 0.25*(
    tex2D(sampler_main, uv2+ss*texsize.zw*float2( 1, 1)).xyz +
    tex2D(sampler_main, uv2+ss*texsize.zw*float2(-1, 1)).xyz +
    tex2D(sampler_main, uv2+ss*texsize.zw*float2( 1,-1)).xyz +
    tex2D(sampler_main, uv2+ss*texsize.zw*float2(-1,-1)).xyz
  );

  // diffusion:  
  ret = tex2D(sampler_main,uv2);//blur;

  float F2 = 0.035;
  float k2 = 0.060;
  float s = 0.025;
  float scale = 9;

  // reaction:
  float3 z = ret;
  float uvv = ret.x*ret.y*ret.y;
  z.x += (-uvv + F2*(1-ret.x) + 0.0007)*scale;
  z.y += (uvv - (F2+k2)*ret.y)*scale;
  //z.x += s*(16-ret.x*ret.y);
  //z.y += s*(ret.x*ret.y - ret.y - ret.z);
  z.z -= 0.02;

  // apply laplacian:
  z.x += (blur - GetPixel(uv2))*0.2*scale;

  ret = z;  
  //ret *= 0.98 + 0.02*saturate( (0.75 - rad )*10 );
  //ret *= 0.99;

  // add noise:
  ret.x += 0.09*(tex2d(sampler_noise_lq, uv*texsize.xy*texsize_noise_lq.zw + rand_frame.xy).xyz*2-1);

  // darken (decay) over time
  //ret = (ret - 0.002)*0.99;
}

LuxXx - Polariflamitization II.comp:
float3 ret1, neu, blur;

shader_body
{
float2 uv2;
float ang2, c, s;
uv -= 0.5;
uv *= aspect.xy;    

float2 tmp = uv;
float dist = 1;
float inten = 1;
float mask = 0;
ret1 = 0;
int anz = 4;
float n = 1;
//uv = mul(uv,float2x2(_qa));
while (n <= anz) {
    ang2 = 6.28*n/anz + q5 * (n-1);
    c = cos(ang2);
    s = sin(ang2);
    uv2.x =  uv.x*c - uv.y*s;
    uv2.y =  uv.x*s + uv.y*c;
    uv2 *= aspect.yx;
    dist = 1-frac(.25 *n+q29); //evtl sqrt !
    dist = dist*dist;
    inten =  pow(dist,.2)*(1-dist)*2;
    float2 uv3 = 3*uv2*dist + .5 + .5*(1-0.5*q28)* float2(q18,q19);;
    neu =  GetPixel (uv3);
    blur = GetBlur1 (frac(uv3));
    neu += blur;
    ret1 = ret1*.9+neu*inten;

n++;
}

uv2 = .5*cos(uv*16);
float3 dots = saturate(.04/length(uv2)) * float3 (1,.7,0);


ret = ret1*.7 + dots * q31;
float3 pol = q17 * saturate (pow(.5/(1+uv.x-4*(frac(time*3))),2));
ret += pol*float3 (0,0,.7);

}

