//                            HSL to RGB  by PieturP
//
// hue         h ( 0 - 0.9 )                          rr ( 0 - 1 )
// saturation  s ( 0 - 1 )            - >             gg ( 0 - 1 )
// luminance   l ( 0 - 1 )                            bb ( 0 - 1 )
//
cc=6*h%6;f=6*h-cc;m=l;p=l*(1-s);q=l*(1-s*f);t=l*(1-s*(1-f));
rr=if(equal(cc,0),m,if(equal(cc,1),q,if(equal(cc,2),p,if(equal(cc,3),p,if(equal(cc,4),t,m)))));
gg=if(equal(cc,0),t,if(equal(cc,1),m,if(equal(cc,2),m,if(equal(cc,3),q,if(equal(cc,4),p,p)))));
bb=if(equal(cc,0),p,if(equal(cc,1),p,if(equal(cc,2),t,if(equal(cc,3),m,if(equal(cc,4),m,q)))));
///////////////////////////////////////////////////////////////////////////////////////////////
