float3 dx,dy,ret1;
float2 zz,uv1,uv2;
float  n1,n2,n3,n4,zv, noise, k1;
static float2 sunpos = float2 (q15,q16)*q19 ;//##!
static float3 suncol = .5+normalize(roam_cos);
static float2x2 ofs = float2x2 (texsize.z,0,0,texsize.w)*2;

float3 cloud (float2 uv_in) {
return saturate(+.0005/abs(length(uv_in-sunpos)-q10/q22))*suncol;}

shader_body {
uv1 = (uv-.5);//*aspect.xy;

dx = tex2D(sampler_main,uv+ofs[0]) - tex2D(sampler_main,uv-ofs[0]);
dy = tex2D(sampler_main,uv+ofs[1]) - tex2D(sampler_main,uv-ofs[1]);
zz = float2(dx.b,dy.b);

//clouds
zv = time*.1 ;
uv2 = q11*uv1+ 0.04*time;
n1 = tex3D(sampler_noisevol_hq,float3 (uv2.x,uv2.y,zv)).b;
n2 = tex3D(sampler_noisevol_hq,float3 (uv2.x*2,uv2.y*2,zv*2)).b;
n3 = tex3D(sampler_noisevol_hq,float3 (uv2.x*4,uv2.y*4,zv*3)).b;
n4 = tex3D(sampler_noisevol_hq,float3 (uv2.x*8,uv2.y*8,zv*7)).b;
noise = n1 + n2/2 + n3/4 + n4/8 -1;

noise = pow(noise,q13); 
uv2 = uv1*(1+.5*q2)+noise*.1; //q2 hier ? ## 

//*******************************
float blur = GetBlur3(uv1/4+.5)+.2;

ret1 = cloud(uv2) ;
ret1 = ret1/blur + tex2D (sampler_main, uv1+.5+q6*zz)*.98-.01-blur*.1-.0*length(zz); 
float go = q12; 
ret = go*ret1 + (1-go)*GetPixel(uv) ;

}

xtramartin (301).comp:
float3 ret1, neu;
float2 uv1, uv2,uv4,rsk,dz1,Kugel1;
float ang2, c, s,rad1,mask1,zoom;
static int n = 1;
static int anz = 4;
int m;

shader_body {

uv = (uv-.5)*aspect.xy;    
//Kugel1
rsk = uv+.2 ;
dz1 = normalize(rsk);
rad1 = 16*length (rsk) ;
uv4 =  tan(rad1)*dz1;
mask1 = saturate(10-7*rad1);
Kugel1 = uv4*mask1;

float2 rs = float2(.1/rad*q15,ang*.2*q22);
float noise = tex2D (sampler_noise_mq,rs);


uv /= 1+ q8*length(uv); //zoom
uv *= 1-q28%2/4;
uv *= 1+q5*noise*rad;
uv *=1; 
ret1 = 0;
while (n <= anz) {
    m = n%2;
    ang2 = 6.28*n/anz*q14 + 0*(n%2-.5)*q9 + q28*3.14/4;//##
    c = cos(ang2);
    s = sin(ang2);
    uv2.x =  uv.x*c - uv.y*s;
    uv2.y =  uv.x*s + uv.y*c ;
    uv2 /= 1+ q26*length(uv)*m; //flash zoom
    uv2 *= 1+(m-.5)*q18; //waber
    if (q3*m == 1) {uv2=uv2.yx;}
    neu = tex2D(sampler_main, uv2 + 0.5); //#
    ret1 = max(ret1,neu-.0);
    n++;
}
ret1 *= ((1-q7)+q7*q25/2);
ret = 1-exp(-ret1*4);
ret = pow(ret,1.5);
ret = lerp(lum(ret),ret,saturate(q20/3));
float4 noise2 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*0.4 
                     );
if(ret.x+ret.y+ret.z<.3)ret /= (noise2)*.5; 
}

