uv *= aspect.xy;    

float dist = 1;
float inten = 1;
ret1 = 0;
int anz = 3;
int n = 1;
while (n <= anz) {
    ang2 = n/anz;
    c = (ang2);
    s = 1-(ang2);
    uv2.x =  uv.x*c - uv.y*s;
    uv2.y =  uv.x*s + uv.y*c;
