shader_body
{

//Code bits by Flexi and Geiss

    float2 d = texsize.zw*6;
    float3 dx = ( GetBlur1(uv+float2(1,0)*d)-GetBlur1(uv-float2(1,0)*d) );
    float3 dy = ( GetBlur1(uv+float2(0,1)*d)-GetBlur1(uv-float2(0,1)*d) );
float2 uv_y = uv-.25*(float2(lum(dx),lum(dy)));
float2 uv_y2 = uv+.25*(float2(lum(dx),lum(dy)));


ret = .8*GetBlur3(uv_y)-GetBlur1(uv_y);
ret += .6*GetBlur1(uv);
ret -= (GetBlur2(uv_y2)-GetBlur1(uv_y2));
ret += 1.2*GetPixel(uv_y2)+.15*GetBlur1(uv_y2);
ret += 1;
ret = lum(ret);
ret = lerp(ret,.75*ret*lum(.6*GetBlur3(uv_y)-.7*GetPixel(uv)-.3*GetBlur1(uv_y2)),pow(hue_shader,ret));
ret *= .8;
ret *= ret;
ret = sqrt(ret);

}

