{

    float2 uv_echo = (uv - 0.5)*1.000*float2(-1,-1) + 0.5;
    ret = lerp( tex2D(sampler_main, uv).xyz, 
                tex2D(sampler_main, uv_echo).xyz, 
                0.50 
              ); //video echo
    ret *= 2.00; //gamma
    float3 retish = 1 - ret*(1-ret)*4; //solarize
float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv_echo.xyy*q28
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q31
                     );
if(ret.x> q26*q13         && ret.x<= q23*q11        )ret.z -= (noise9).x*.5; 
if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5; 
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5; 
    ret = float3(retish[int(bass*roam_sin.x)]*0.5,
                 retish[int(treb*roam_cos.y)]*0.5,
                 retish[int(mid *roam_sin.z)]);
    ret *= 0.5;
ret-=slow_roam_sin.wzy*roam_cos.zxy;
}

