float2 uv0, uv1, uv2,uv4,rsk,dz1,Kugel1;;
static const float sw1 =  (rand_preset.x) >= .4;
static const float sw2 =  (rand_preset.y);

shader_body {
uv0 = uv;
uv2 = float2(.2/rad+time/4,ang/3.14)*2;
float mod = length(sin(uv2*3.141/2+time*.1));
float2 noise = tex2D (sampler_noise_hq,uv2+mod).rg;
float mask = (noise.r <= sw2);
float2 rohr = sw1*rad * (noise-.5) /2*mask;

uv1 = float2(1-uv.x,uv.y);
ret =  GetPixel(uv)+GetPixel(uv1);

float3 back = .2*(.5+(uv.x-.5)*q1+(uv.y-.5)*q2);
uv+= rohr * sw1;

uv1 = float2(1-uv.x,uv.y);
ret += (GetBlur2(uv) + GetBlur2(uv1)) *min(.5+treb_att/4,2) *(1+1*sw1) * saturate(1-lum(ret)/2);
ret += !sw1*back;
ret = lerp(ret*(hue_shader*2-1),ret,lum(ret));;
float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy*q28
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q30 
                     );
if(ret.x> q26*roam_cos.y && ret.x<= q23*roam_sin.x)ret.z += (noise9).x*.5; 
if(ret.y> q25*roam_sin.x && ret.y<= q22*roam_cos.x)ret.x += (noise9).y*.5; 
if(ret.z> q24*roam_cos.x && ret.z<= q21*roam_sin.y)ret.y += (noise9).z*.5; 
}

