#define snh sampler_noise_hq
sampler sampler_heart;
sampler sampler_pw_noise_lq;
float3 neon, neons, col;
float2 water, uv0, uv1, uv2, uv5, dz, tuv0, tuv, tshift;
float near, noise, z, k1, ftu, nshape, nmask, iswater;
bool istube;
static const int anz = 20, tubes = 12;
static float trad = 0.008, tlen = q7; 

float tria (float x) {return abs(2*frac(x/2)-1);}

shader_body {
uv += float2(q17,q18);
uv0 = uv;
uv1 = (uv-0.5)*aspect.xy ;
z = q8/uv1.y;
uv2 = float2 (z*uv1.x,z+q19);
z  *= 1+0.14*q11*sin(uv2.y+q10*M_PI);
uv2 = float2 (z*uv1.x,z+q19);

water = tex2D (snh, uv2) + tex2D (snh,uv2*2+float2(0,q19/2))/2-0.7;
iswater = (z>0)* sat((5-15*abs(uv1.x)*z) /z);
uv += water * 0.04 *iswater;

//NEON
uv1 = (uv-0.5)*aspect.xy ; 
tuv0 = float2 (.5/length (uv1), atan2(uv1.x,-uv1.y)/M_PI) ;
near = sat (2-tuv0.x/5);
tuv = tuv0 + float2(q19,0);
ftu = frac (tuv.y*tubes/2)-0.5; 
nshape = saturate(1-1/trad*pow (ftu,2));
tuv.x -= nshape*2.5*sqrt(trad)/tubes*tuv0.x;
k1 = abs(sin(tuv.x/tlen*M_PI*2));
nshape *= sat(k1*2);
istube = nshape >0;
uv5  = tuv*float2(0.25/tlen,tubes/16.0); 
col = (tex2D(sampler_pw_noise_lq,uv5/32)+0.2);

neon = pow(nshape,0.41)*sat(8*k1)*col;
neons= 1.4*sat(k1)* saturate(exp(-5*abs(ftu))) * col ;

float dir = (int(uv5.y*16)%tubes)/2;
