shader_body
{

//Code bits by Flexi and Geiss
//Shader composition by Stahlregen

    float2 d = texsize.zw*6;
    float3 dx = ( GetBlur1(uv+float2(1,0)*d)-GetBlur1(uv-float2(1,0)*d) );
    float3 dy = ( GetBlur1(uv+float2(0,1)*d)-GetBlur1(uv-float2(0,1)*d) );
float2 uv_y = uv-0.25*(float2(lum(dx),lum(dy)));

ret = .5*GetBlur3(uv);
ret -= (GetBlur2(uv)-.01);
ret += GetPixel(uv)+GetBlur1(uv)*.15-.01;
ret += .75;
ret = lum(ret);
ret = lerp(ret,ret*lum(GetBlur3(uv_y)-GetBlur1(uv_y)),pow(hue_shader,ret));

float3 ret2 = -.5*GetBlur3(uv_y);
ret2 += GetBlur1(uv_y);
ret2 -= GetPixel(uv_y);
ret2 -= .75;
ret2 = lum(ret2);
ret2 = lerp(ret2,ret2*lum(GetBlur3(uv)-GetBlur1(uv)),pow(hue_shader.zxy,ret));

ret = abs(ret-2*ret2);
//ret = ret2;

ret -= .175*sqrt(ret);
ret *= ret;
}

