shifter - dark tides bdrv mix.warp:
shader_body
{
    // sample previous frame
    ret = tex2D( sampler_fc_main, uv ).xyz;

    // darken (decay) over time
    ret *= 1.00; //or try: ret -= 0.004;
//    ret = tex2D( sampler_pw_main, uv ).xyz;

    // darken over time
//    ret -= 0.004;//*= 0.95; //or try: ret -= 0.004;

ret.xyz = tex2D(sampler_main, uv_orig).xyz*float3(.97,1,.97) - float3(.03,0,.03);

ret.z += GetBlur1(uv_orig).z*.45;
ret.x += GetBlur1(uv_orig).z*.05 + GetBlur3(uv_orig).z*.05;
ret.z -= ret.x;

float2 pixelsize = texsize.zw;
ret.y = saturate(tex2D( sampler_pw_main,uv_orig).y);

float1 conway = tex2D( sampler_pw_main, uv_orig + float2(-1,-1)*pixelsize).y;
       conway += tex2D( sampler_pw_main, uv_orig + float2(0,-1)*pixelsize).y;
       conway += tex2D( sampler_pw_main, uv_orig + float2(1,-1)*pixelsize).y;
       conway += tex2D( sampler_pw_main, uv_orig + float2(-1,0)*pixelsize).y;
       conway += tex2D( sampler_pw_main, uv_orig + float2(1,0)*pixelsize).y;
       conway += tex2D( sampler_pw_main, uv_orig + float2(-1,1)*pixelsize).y;
       conway += tex2D( sampler_pw_main, uv_orig + float2(0,1)*pixelsize).y;
       conway += tex2D( sampler_pw_main, uv_orig + float2(1,1)*pixelsize).y;

float1 test = q5*(1-GetBlur1(uv_orig).y)*(1-GetBlur2(uv_orig).y)*(1-GetBlur3(uv_orig).y);

conway -= tex2D( sampler_pw_main, uv_orig).x;
ret=ret*.98;
}

shifter - dark tides bdrv mix.comp:
sampler sampler_lichen;
shader_body
{
  ret = tex2D(sampler_main,uv).xyz;
  float3 d = float3(texsize.zw, 0)*1.3;
    float b1 = lum(GetBlur1(uv + d.xz));
    float b2 = lum(GetBlur1(uv - d.xz));
    float b3 = lum(GetBlur1(uv + d.zy));
    float b4 = lum(GetBlur1(uv - d.zy));

    ret *= .75; 
    ret += (b1-b2)*3*float3(1,0.7,0.3);
    ret += (b3-b4)*3*float3(0.2,0.5,0.7);

    ret = pow(ret,1.2)*1.5;
}

