float3 noiseVal =.03*(tex2D(sampler_noise_lq, uv*.3+.01*rand_frame));
noiseVal = .01;
float3 Feedback = GetBlur1(1-uv);

float2 zz = uv1 *texsize.xy *.015;
//zz =mul(zz,float2x2(_qa));
zz = zz.yx;
float2 h1 = clamp(tan(zz.yx),-12,12) * cos(4*(q2+1)*zz);

